BEGIN;
UPDATE questions SET choice_a = '大量のデータを高速処理するためのデータベース管理技術', choice_b = 'インターネットを介し、複数のコンピュータを連携する通信技術', choice_c = '人間の知的活動をコンピュータで実現する技術の総称', choice_d = 'コンピュータのハードウェアを小型・高速化する半導体技術', correct_answer = 'C', incorrect_explanation = 'A: データベース管理はデータ保管・検索のための技術で、AIの定義には該当しない（誤り）
B: 通信技術はネットワーク領域の話題で、AIとは異なる（誤り）
C: 人間の知的活動をコンピュータで実現する技術の総称（正解）
D: 半導体技術はハードウェアの話題で、AIとは別の概念（誤り）' WHERE question_id = 'Q1-001';
UPDATE questions SET choice_a = '入力データの分類・識別を主たる目的とするAI', choice_b = 'テキスト、画像、音声などのコンテンツを新たに生成するAI', choice_c = 'センサーデータをリアルタイムで解析することを目的とするAI', choice_d = '過去データから将来の数値を予測することを目的とするAI', correct_answer = 'B', incorrect_explanation = 'A: 分類・識別は識別系AIの説明であり、生成AIとは異なる（誤り）
B: テキスト、画像、音声などのコンテンツを新たに生成するAI（正解）
C: センサーデータのリアルタイム解析はIoTやエッジAIの領域（誤り）
D: 数値予測は予測系AIの説明であり、生成AIとは異なる（誤り）' WHERE question_id = 'Q1-004';
UPDATE questions SET choice_a = '外部システムからAIモデルの機能を呼び出す接続口の役割', choice_b = 'ユーザーの入力データを自動でバックアップする役割', choice_c = 'AIモデルの学習データを暗号化して保護する役割', choice_d = 'AIモデルのパラメータを定期的に最適化する役割', correct_answer = 'A', incorrect_explanation = 'A: 外部システムからAIモデルの機能を呼び出す接続口の役割（正解）
B: バックアップはストレージ管理の機能で、APIの役割ではない（誤り）
C: 暗号化はセキュリティ機能で、APIの本来の役割ではない（誤り）
D: パラメータ最適化は学習アルゴリズムの機能で、APIとは異なる（誤り）' WHERE question_id = 'Q1-016';
UPDATE questions SET choice_a = '患者データを院内に保管し、外部へのデータ流出リスクを抑えられるため', choice_b = 'クラウドベンダーが最新のAIモデルへ自動更新を行うため', choice_c = 'クラウドより初期導入コストを抑えられる傾向があるため', choice_d = 'インターネット接続がない環境でも高性能なAI処理を継続できるため', correct_answer = 'A', incorrect_explanation = 'A: 患者データを院内に保管し、外部へのデータ流出リスクを抑えられるため（正解）
B: 自動更新はクラウドサービスの特徴で、オンプレミスでは手動更新が一般的（誤り）
C: オンプレミスはハードウェア導入の初期費用が大きく、コストを抑えにくい（誤り）
D: オンプレミスでも一般にネットワーク接続を併用するため、必須要件ではない（誤り）' WHERE question_id = 'Q1-017';
UPDATE questions SET choice_a = '特定のタスクを想定して設計された小規模なモデル', choice_b = '大量のデータで学習され、多様なタスクに適応可能な汎用性の高いモデル', choice_c = '医療分野に最適化された専門特化型のモデル', choice_d = 'ルールベースで動作する従来型のエキスパートシステム', correct_answer = 'B', incorrect_explanation = 'A: 基盤モデルは小規模・特化ではなく、汎用性と大規模性が特徴（誤り）
B: 大量のデータで学習され、多様なタスクに適応可能な汎用性の高いモデル（正解）
C: 医療特化型は基盤モデルから派生する応用形態で、定義そのものではない（誤り）
D: 基盤モデルは深層学習ベースで、ルールベースのエキスパートシステムとは技術が異なる（誤り）' WHERE question_id = 'Q1-019';
UPDATE questions SET choice_a = '教師あり学習で過去の再入院有無をラベルとして学習させる', choice_b = '教師なし学習で患者データをクラスタリングし、再入院傾向を把握する', choice_c = '画像認識用の転移学習を再入院予測タスクへ流用する', choice_d = '報酬を設計した強化学習で、再入院抑制行動を学習させる', correct_answer = 'A', incorrect_explanation = 'A: 教師あり学習で過去の再入院有無をラベルとして学習させる（正解）
B: クラスタリングは集団分割で、ラベル予測には直接結びつかない（誤り）
C: 画像系の転移学習を異種データの予測へ流用するのは難しい（誤り）
D: 強化学習は環境との相互作用を前提とし、静的データ予測には不向き（誤り）' WHERE question_id = 'Q1-021';
UPDATE questions SET choice_a = '生成AIの出力を診療場面で運用し、患者の反応に基づいて事後修正する', choice_b = 'ハルシネーション対策に特化した生成AIサービスへ切り替える', choice_c = '生成AIの出力を医師が確認し、医学的根拠に照らして内容を検証する', choice_d = '生成AIへの入力プロンプトを簡潔化し、回答の範囲を限定する', correct_answer = 'C', incorrect_explanation = 'A: 事後修正では誤情報が患者に届く可能性があり、対策として不十分（誤り）
B: 特化サービスへの切替だけでは誤情報の発生を完全には抑えられない（誤り）
C: 生成AIの出力を医師が確認し、医学的根拠に照らして内容を検証する（正解）
D: 入力簡潔化は誤情報の根本対策ではない（誤り）' WHERE question_id = 'Q1-025';
UPDATE questions SET choice_a = '学習データ量を増やすため、診療記録を可能な限り多く活用する', choice_b = 'ファインチューニング後は元の汎用能力が低下することがあるため、対象タスクに集中させる', choice_c = '学習データの医学的正確性、個人情報保護、倫理審査の3点を確認する', choice_d = 'ファインチューニングは特定の高性能GPU環境を必要とし、自組織での実施は計画的に検討する', correct_answer = 'C', incorrect_explanation = 'A: 学習データの量より、匿名化・倫理審査などの適切な処理が優先される（誤り）
B: 元能力低下に注意は妥当だが、医療特化で最重要なのは正確性と倫理面（誤り）
C: 学習データの医学的正確性、個人情報保護、倫理審査の3点を確認する（正解）
D: 計画的検討は必要だが、医療特化で最重要なのは正確性と倫理面（誤り）' WHERE question_id = 'Q1-033';
UPDATE questions SET choice_a = '問診内容（テキスト）と皮膚病変写真（画像）を組合せて診断を支援する', choice_b = '電子カルテのテキストデータを音声で読上げ、医師の確認業務を支援する', choice_c = '胸部X線画像から異常領域を検出し、医師の読影を支援する', choice_d = '複数患者の検査値を時系列でグラフ化し、状態変化の把握を支援する', correct_answer = 'A', incorrect_explanation = 'A: 問診内容（テキスト）と皮膚病変写真（画像）を組合せて診断を支援する（正解）
B: テキスト→音声の単一モーダル変換であり、複数種類のデータを統合していない（誤り）
C: 画像のみを扱う単一モーダルAIであり、マルチモーダルではない（誤り）
D: 数値データのみを扱う単一モーダル処理である（誤り）' WHERE question_id = 'Q1-036';
UPDATE questions SET choice_a = 'オープンソースモデルは、開発元のサポートが商用モデルより手厚く長期運用に向く', choice_b = '医療機関のニーズに応じ、セキュリティ・コスト・性能・サポート体制を総合評価する', choice_c = '商用モデルは医療用途で薬機法上の承認が不要となり、導入手続きが簡略化される', choice_d = 'プロプライエタリモデルはモデル内部を医療機関が修正できるため、独自カスタマイズに向く', correct_answer = 'B', incorrect_explanation = 'A: 一般にサポートは商用モデルの方が手厚く、OSSは自組織で対応が必要（誤り）
B: 医療機関のニーズに応じ、セキュリティ・コスト・性能・サポート体制を総合評価する（正解）
C: 医療機器該当性は使用目的で決まり、商用かどうかと薬機法手続きの要否は別問題（誤り）
D: 内部修正が可能なのは一般にOSSであり、商用モデルは内部仕様非公開のことが多い（誤り）' WHERE question_id = 'Q1-039';
UPDATE questions SET choice_a = '医療機関内の電子カルテデータを匿名化したテキスト集を活用する', choice_b = 'ウェブページ、書籍、論文などインターネット上の大量のテキストデータを使用する', choice_c = 'AIサービス利用者が入力したプロンプトの履歴を学習対象に含める', choice_d = 'プログラミング言語のソースコードを中心に学習する', correct_answer = 'B', incorrect_explanation = 'A: 一部のドメイン特化LLMでは利用されるが、汎用LLMの事前学習データの中心ではない（誤り）
B: ウェブページ、書籍、論文などインターネット上の大量のテキストデータを使用する（正解）
C: 利用者の入力はファインチューニング等で使われ得るが、事前学習データの中心ではない（誤り）
D: コード中心の学習はコード生成特化モデルの特徴であり、汎用LLMの中心ではない（誤り）' WHERE question_id = 'Q1-040';
UPDATE questions SET choice_a = 'ファインチューニングよりも計算リソースが少なくて済む傾向があり、運用負荷が下がる', choice_b = 'モデルの再学習が不要で、知識ベースの更新だけで最新情報に対応できる', choice_c = 'ファインチューニングよりも応答速度が速くなり、リアルタイム処理に向く', choice_d = 'ファインチューニングよりも医療専門用語のニュアンスを深く理解できる', correct_answer = 'B', incorrect_explanation = 'A: 学習コストは下がるが、検索処理が加わるため運用負荷が単純に下がるとは限らない（誤り）
B: モデルの再学習が不要で、知識ベースの更新だけで最新情報に対応できる（正解）
C: 検索処理が加わるためファインチューニングより応答が遅くなる場合がある（誤り）
D: ニュアンス理解はモデル自体の能力に依存し、RAGはあくまで参照情報を補う仕組み（誤り）' WHERE question_id = 'Q1-042';
UPDATE questions SET choice_a = '基盤モデルは医療専用に最適化されているため、他分野への応用が難しい', choice_b = '汎用的に学習されているため、医療特有の専門用語や概念の理解が不十分な場合がある', choice_c = '基盤モデルは小規模で、複雑な多モーダルタスクには対応しづらい', choice_d = '基盤モデルはオープンソース主体で、商用利用に制約があることが多い', correct_answer = 'B', incorrect_explanation = 'A: 基盤モデルは汎用設計で、他分野への応用も活発（誤り）
B: 汎用的に学習されているため、医療特有の専門用語や概念の理解が不十分な場合がある（正解）
C: 基盤モデルは大規模で、複雑なタスクにも対応できる設計が一般的（誤り）
D: 商用とオープンソースの両形態が存在し、ライセンスはモデルごとに異なる（誤り）' WHERE question_id = 'Q1-043';
UPDATE questions SET choice_a = 'AIが入力データをどう処理し、どんな出力を生成するかで分類する', choice_b = 'AI開発元の所在地と企業規模を踏まえて分類する', choice_c = 'AI動作に必要なハードウェア構成と処理能力で分類する', choice_d = 'AIサービスの価格帯と契約形態で分類する', correct_answer = 'A', incorrect_explanation = 'A: AIが入力データをどう処理し、どんな出力を生成するかで分類する（正解）
B: 開発元の属性は機能的分類の基準にはならない（誤り）
C: ハードウェア要件は実装上の話題で、機能的分類とは異なる（誤り）
D: 価格帯や契約形態はビジネス上の分類で、機能的分類とは異なる（誤り）' WHERE question_id = 'Q1-044';
UPDATE questions SET choice_a = '問診内容を聞き取り、可能性のある疾患候補を医師に提示する', choice_b = '問診結果に基づき処方薬を選定し、薬局向けの処方データを生成する', choice_c = '問診内容から最終診断を確定し、患者へ診断書を発行する', choice_d = '問診を起点に検査・治療計画を組み立て、自律的に実行する', correct_answer = 'A', incorrect_explanation = 'A: 問診内容を聞き取り、可能性のある疾患候補を医師に提示する（正解）
B: 処方は医師の医行為で、AIが単独で行うことはできない（誤り）
C: 診断確定は医師の医行為で、AIの役割は支援に限られる（誤り）
D: 検査・治療計画の実行はAI単独では行えない（誤り）' WHERE question_id = 'Q2-001';
UPDATE questions SET choice_a = '医師の指示や監督なしに、AIが診断と治療の決定を行うシステム', choice_b = '病院の経営指標や受診状況を分析し、可視化を行うシステム', choice_c = '医療従事者の研修記録と継続学習を管理するシステム', choice_d = '患者データやエビデンスに基づき、診断・治療判断の参考情報を医師に提示するシステム', correct_answer = 'D', incorrect_explanation = 'A: 医師の判断を代替するシステムではなく、判断を支援するのがCDSの役割（誤り）
B: 経営支援システム（BI）の説明であり、臨床判断支援ではない（誤り）
C: 研修管理システムの説明であり、診療支援ではない（誤り）
D: 患者データやエビデンスに基づき、診断・治療判断の参考情報を医師に提示するシステム（正解）' WHERE question_id = 'Q2-002';
UPDATE questions SET choice_a = 'AIが診断内容を文書化し、医師の追認を経ずにカルテへ反映する', choice_b = 'AIが診断書の下書きを生成し、押印・交付までを一連で処理する', choice_c = 'AIが生成した紹介状の下書きを医師が確認・修正してから発行する', choice_d = 'AIが処方データを生成し、薬局システムへ直接送信する', correct_answer = 'C', incorrect_explanation = 'A: 医師の追認を経ない反映は文書の真正性を損なう（誤り）
B: 診断書は医師の責任で交付されるべき書類（誤り）
C: AIが生成した紹介状の下書きを医師が確認・修正してから発行する（正解）
D: 処方データの直接送信はAI単独では完結しない医行為（誤り）' WHERE question_id = 'Q2-003';
UPDATE questions SET choice_a = 'AIが生成した説明文書を、患者の手元に渡る直前に看護師が確認して交付する', choice_b = 'AIが推奨する治療法を中心に説明し、代替案は患者から質問があれば追加で提示する', choice_c = '説明文書の下書きをAIに生成させ、医師が内容を確認・修正してから使用する', choice_d = 'AIに患者と対話させて理解度を判定させ、その後に医師が補足説明を行う', correct_answer = 'C', incorrect_explanation = 'A: ICの説明責任は医師にあり、看護師の確認だけでは不十分（誤り）
B: 治療選択肢は積極的に提示すべきで、質問待ちでは患者の自律性を損なう（誤り）
C: 説明文書の下書きをAIに生成させ、医師が内容を確認・修正してから使用する（正解）
D: 理解度判定や説明の中心は医師が担うべきで、AI主導の対話は不適切（誤り）' WHERE question_id = 'Q2-004';
UPDATE questions SET choice_a = 'バイタルの異常をAIが検知した場合、医師への報告判断もAIに任せる', choice_b = '夜勤の申し送り事項をAIに口述入力し、要約を確認してから引き継ぐ', choice_c = 'AIが提案したケアプランをそのまま当日の業務に組み込む', choice_d = '患者情報を含む看護記録を、汎用AIチャットサービスで要約させる', correct_answer = 'B', incorrect_explanation = 'A: 医師への報告判断は看護師の責任で行う（誤り）
B: 夜勤の申し送り事項をAIに口述入力し、要約を確認してから引き継ぐ（正解）
C: AI提案のケアプランは看護師の判断を経て採否を決める（誤り）
D: 個人情報を汎用サービスへ入力する運用は情報管理上不適切（誤り）' WHERE question_id = 'Q2-005';
UPDATE questions SET choice_a = '処方内容の整合性をAIが判定し、変更を施した上で薬局へ送信する', choice_b = '医師の処方を再評価し、必要があれば差し戻し判断をAIに委ねる', choice_c = '服薬指導文書の下書きをAIが作成し、薬剤師が確認・修正して使用する', choice_d = '副作用が想定される薬剤について、AIが患者へ直接服薬調整を案内する', correct_answer = 'C', incorrect_explanation = 'A: 処方変更は医師の判断によるべきで、AIが施す運用は不適切（誤り）
B: 処方の差し戻し判断は薬剤師・医師の責務（誤り）
C: 服薬指導文書の下書きをAIが作成し、薬剤師が確認・修正して使用する（正解）
D: 服薬調整の指示は医療職が行うべきで、AI単独で患者へ伝えるのは不適切（誤り）' WHERE question_id = 'Q2-006';
UPDATE questions SET choice_a = 'AIが生成した内容を院内の複数医療者で査読し、合意が得られた表現を採用する', choice_b = '専門用語と一般的な言い換えを併記し、患者が状況に応じて選べる形式にする', choice_c = '患者の理解度に合わせた平易な表現を用い、医療者が内容を確認してから提供する', choice_d = '最新の論文を引用元として記載し、根拠の出典を明確化する', correct_answer = 'C', incorrect_explanation = 'A: 査読は丁寧だが、患者の理解しやすさが優先課題で運用も非現実的（誤り）
B: 言い換え併記は補助になるが、専門用語が残ると患者の理解を妨げやすい（誤り）
C: 患者の理解度に合わせた平易な表現を用い、医療者が内容を確認してから提供する（正解）
D: 論文引用は学術的だが、患者向け資料の主目的は理解しやすさ（誤り）' WHERE question_id = 'Q2-007';
UPDATE questions SET choice_a = 'AIが軽症と判定した患者を診察前に帰宅させ、再来院基準を案内する', choice_b = 'AIの判定結果を参考にしつつ、最終的な緊急度判定は医療従事者が行う', choice_c = 'AIが算出した緊急度に従い、診察順序を自動的に並び替える', choice_d = 'AIの判定結果を待合の表示板に直接表示し、患者の待ち時間を案内する', correct_answer = 'B', incorrect_explanation = 'A: 軽症判定だけで診察を省略するのはトリアージとして不適切（誤り）
B: AIの判定結果を参考にしつつ、最終的な緊急度判定は医療従事者が行う（正解）
C: 診察順序の決定は医療者の総合判断によるべき（誤り）
D: 患者へ直接表示する運用は誤解や対応遅延を生む可能性が高い（誤り）' WHERE question_id = 'Q2-008';
